    }
}

class Box {
    int value;
    Box(int value) {
        this.value = value;
    }
}
public class Main {
    public static void main(String[] args) {
        Box[] boxes = { new Box(1), new Box(2) };
        for (Box b : boxes) {
            b.value += 10;
            b = new Box(99);
        }
        System.out.print(boxes[0].value + ":" + boxes[1].value);
    }
}

class Parent {
    Parent() {
        print();
    }
    void print() {
        System.out.print("P");
    }
}
class Child extends Parent {
    int value = 7;
    @Override void print() {
        System.out.print("C" + value + ":");
    }
    Child() {
        System.out.print(value);
    }
}
public class Main {
    public static void main(String[] args) {
        new Child();
    }
}

interface A {
    default String name() { return "A"; }
    static String kind() { return "K"; }
}
abstract class B implements A {
    public abstract String name();
}
class C extends B {
    @Override public String name() { return "C"; }
}
public class Main {
    public static void main(String[] args) {
        A x = new C();
        System.out.print(x.name() + ":" + A.kind());
    }
}

